fn find_min(a: &[i32], lo: usize) -> usize {
    // Initialize the index of the minimum to `lo`
    let mut min_idx = lo;
    // Scan the rest of the slice from lo+1 to end
    for i in lo + 1..a.len() {
        if a[i] < a[min_idx] {
            min_idx = i;
        }
    }
    min_idx
}

